const raw = $input.first().json;
const body = raw.body ?? raw;
const allowedEvents = new Set([
  'project.created',
  'agent.prepared',
  'agent.output_submitted',
  'agent.validated',
  'qa.approved',
  'delivery.ready',
]);

const projectId = body.project_id;
const eventType = body.event_type;
const agent = body.agent ?? null;
const status = body.status ?? null;

if (!projectId || !eventType) {
  return [{
    json: {
      ok: false,
      error: 'project_id and event_type are required',
      accepted_events: Array.from(allowedEvents),
    },
  }];
}

if (!allowedEvents.has(eventType)) {
  return [{
    json: {
      ok: false,
      project_id: projectId,
      event_type: eventType,
      error: 'Unsupported event_type',
      accepted_events: Array.from(allowedEvents),
    },
  }];
}

let recommendedAction = 'record_event';
let operatorCommand = null;

if (eventType === 'project.created') {
  recommendedAction = 'prepare_eval_agent';
  operatorCommand = `python3 execution/agency.py prepare eval-agent ${projectId}`;
}

if (eventType === 'agent.output_submitted' && agent) {
  recommendedAction = 'validate_agent_output';
  operatorCommand = `python3 execution/agency.py validate ${agent} ${projectId}`;
}

if (eventType === 'agent.validated') {
  recommendedAction = 'ask_runner_for_next_action';
  operatorCommand = `python3 execution/agency.py next ${projectId}`;
}

if (eventType === 'delivery.ready' || eventType === 'qa.approved') {
  recommendedAction = 'sync_supabase_dry_run';
  operatorCommand = `python3 execution/agency.py sync-supabase ${projectId}`;
}

return [{
  json: {
    ok: true,
    project_id: projectId,
    event_type: eventType,
    agent,
    status,
    recommended_action: recommendedAction,
    operator_command: operatorCommand,
    zero_api_runtime: true,
    ceo_approval_required_for_external_actions: true,
  },
}];
